"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type OrbitDragItem = {
  id: string;
  label: string;
};

export type OrbitDragProps = {
  items: OrbitDragItem[];
  className?: string;
  onOrderChange?: (ids: string[]) => void;
};

/**
 * Drag chips around an orbital ring; release snaps to the nearest slot.
 */
function OrbitDrag({ items, className, onOrderChange }: OrbitDragProps) {
  const [order, setOrder] = React.useState(items.map((i) => i.id));
  const [dragging, setDragging] = React.useState<string | null>(null);
  const [angleOffset, setAngleOffset] = React.useState(0);
  const startRef = React.useRef<{ angle: number; pointer: number } | null>(null);

  React.useEffect(() => {
    setOrder(items.map((i) => i.id));
  }, [items]);

  const byId = React.useMemo(
    () => Object.fromEntries(items.map((i) => [i.id, i])),
    [items],
  );

  const onPointerDown = (id: string, e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    const el = e.currentTarget.parentElement?.getBoundingClientRect();
    if (!el) return;
    const cx = el.left + el.width / 2;
    const cy = el.top + el.height / 2;
    const pointer = Math.atan2(e.clientY - cy, e.clientX - cx);
    startRef.current = { angle: angleOffset, pointer };
    setDragging(id);
  };

  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragging || !startRef.current) return;
    const el = e.currentTarget.getBoundingClientRect();
    const cx = el.left + el.width / 2;
    const cy = el.top + el.height / 2;
    const pointer = Math.atan2(e.clientY - cy, e.clientX - cx);
    setAngleOffset(
      startRef.current.angle + (pointer - startRef.current.pointer),
    );
  };

  const onPointerUp = () => {
    if (!dragging) return;
    const step = (Math.PI * 2) / Math.max(order.length, 1);
    const snapped = Math.round(angleOffset / step) * step;
    const shift = Math.round(angleOffset / step);
    setAngleOffset(snapped);
    if (shift !== 0) {
      const next = [...order];
      const n = ((shift % next.length) + next.length) % next.length;
      const rotated = [...next.slice(n), ...next.slice(0, n)];
      setOrder(rotated);
      onOrderChange?.(rotated);
      setAngleOffset(0);
    }
    setDragging(null);
    startRef.current = null;
  };

  return (
    <div
      className={cn(
        "relative mx-auto aspect-square w-full max-w-[280px] touch-none select-none",
        className,
      )}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
    >
      <div
        aria-hidden
        className="absolute inset-8 rounded-full border border-dashed border-border"
      />
      {order.map((id, i) => {
        const item = byId[id];
        if (!item) return null;
        const base = (-Math.PI / 2) + (Math.PI * 2 * i) / order.length;
        const a = base + angleOffset;
        const r = 42;
        return (
          <button
            key={id}
            type="button"
            onPointerDown={(e) => onPointerDown(id, e)}
            className={cn(
              "absolute left-1/2 top-1/2 z-[1] -translate-x-1/2 -translate-y-1/2 rounded-full border border-border bg-card px-3 py-1.5 text-xs font-medium shadow-[var(--shadow-soft)] transition-shadow",
              dragging === id && "shadow-[var(--shadow-lift)] ring-2 ring-primary/30",
            )}
            style={{
              transform: `translate(calc(-50% + ${Math.cos(a) * r}%), calc(-50% + ${Math.sin(a) * r}%))`,
            }}
          >
            {item.label}
          </button>
        );
      })}
      <div className="absolute inset-0 grid place-items-center text-[11px] text-muted-foreground">
        Drag orbit
      </div>
    </div>
  );
}

export { OrbitDrag };
